// Retrieve the current machine state from context
let state = context.get("state") || {};

// Get the parameter name (Temperature, Current, etc.)
const parameter = msg.browseName;

if (!parameter) {
    return null;
}

// Save the latest value
state[parameter.toLowerCase()] = msg.payload;

// Save updated state
context.set("state", state);

// Publish only when all measurements are available
if (
    state.temperature !== undefined &&
    state.vibration !== undefined &&
    state.current !== undefined &&
    state.mode !== undefined
) {

    let out = {};

    out.topic = "factory/pump01/state";

    out.payload = {
        asset: "Pump-01",
        timestamp: new Date().toISOString(),
        measurements: {
            temperature: state.temperature,
            vibration: state.vibration,
            current: state.current,
            mode: state.mode
        }
    };

    return out;
}

// Wait until all four values are available
return null;

const data = msg.payload;

// Validate structure
if (!data || !data.measurements) {
    node.warn("Invalid payload");
    return null;
}

const m = data.measurements;

// Measurement name
msg.measurement = "pump_sensors";

// Payload for InfluxDB
msg.payload = {
    tags: {
        asset: data.asset
    },
    fields: {
        temperature: Number(m.temperature),
        vibration: Number(m.vibration),
        current: Number(m.current),
        mode: String(m.mode)
    },
    timestamp: new Date(data.timestamp)
};

return msg;

const data = msg.payload;

if (!data || !data.measurements) {
    node.warn("Invalid payload — missing measurements");
    return null;
}

const m = data.measurements;

if (
    m.temperature === undefined ||
    m.vibration === undefined ||
    m.current === undefined ||
    m.mode === undefined
) {
    node.warn("Incomplete measurements");
    return null;
}

// Measurement name
msg.measurement = "pump_sensors";

// [0] = fields
// [1] = tags
msg.payload = [
    {
        temperature: Number(m.temperature),
        vibration: Number(m.vibration),
        current: Number(m.current),
        mode: String(m.mode)
    },
    {
        asset: String(data.asset)
    }
];

return msg;

// ─── ML Diagnostics → InfluxDB Writer ────────────────────────────────────────
// Adapts the new ml_service output to InfluxDB line protocol via influxdb out node.
// Writes both numeric fields (for charts) and string fields (for stat panels).

const data = msg.payload;

if (!data || data.is_anomaly === undefined) {
    node.warn("Invalid ML payload — missing is_anomaly field");
    return null;
}

// Safe nested value extractor
const get = (obj, path, fallback = null) => {
    try {
        const val = path.split('.').reduce((o, k) => o?.[k], obj);
        return val !== undefined && val !== null ? val : fallback;
    } catch { return fallback; }
};

// Numeric severity code for time series plotting and threshold coloring
// 0 = NORMAL, 1 = WARNING, 2 = CRITICAL
const severityMap = { "NORMAL": 0, "WARNING": 1, "CRITICAL": 2 };

const diagStatus   = get(data, 'diagnosis.status', 'NO_DIAGNOSIS');
const hasDiagnosis = diagStatus === 'HYPOTHESIS_AVAILABLE';

const mostLikely  = hasDiagnosis ? get(data, 'diagnosis.most_likely', 'none') : 'none';
const confidence  = hasDiagnosis ? get(data, 'diagnosis.confidence', 'LOW')   : 'LOW';

const alt1 = (hasDiagnosis && data.diagnosis?.alternatives?.[0])
    ? data.diagnosis.alternatives[0].fault : 'none';
const alt2 = (hasDiagnosis && data.diagnosis?.alternatives?.[1])
    ? data.diagnosis.alternatives[1].fault : 'none';

const recMessage  = get(data, 'recommendation.message',  'No action required.');
const recAction   = get(data, 'recommendation.action',   'CONTINUE_MONITORING');
const recPriority = get(data, 'recommendation.priority', 'NONE');

msg.measurement = "ml_diagnostics";

msg.payload = [
    // ── FIELDS (values stored in InfluxDB) ──────────────────────────────────
    {
        // Numeric fields — used for time series charts and threshold coloring
        is_anomaly      : data.is_anomaly ? 1 : 0,
        anomaly_score   : Number(data.anomaly_score ?? 0),
        health_score    : Number(((1 - (data.anomaly_score ?? 0)) * 100).toFixed(1)),
        severity_code   : Number(severityMap[data.severity] ?? 0),
        z_score_deviation: Number(get(data, 'evidence.z_score_deviation', 0)),
        z_temperature   : Number(get(data, 'evidence.z_scores.temperature', 0)),
        z_vibration     : Number(get(data, 'evidence.z_scores.vibration',   0)),
        z_current       : Number(get(data, 'evidence.z_scores.current',     0)),
        support_score   : Number(hasDiagnosis ? get(data, 'diagnosis.support_score', 0) : 0),

        // String fields — used for stat panels showing labels and text
        severity        : String(data.severity ?? 'NORMAL'),
        dominant_feature: String(get(data, 'evidence.dominant_feature', 'none')),
        diagnosis       : String(mostLikely),
        confidence      : String(confidence),
        alternative_1   : String(alt1),
        alternative_2   : String(alt2),
        recommendation  : String(recMessage),
        action          : String(recAction),
        priority        : String(recPriority)
    },
    // ── TAGS (metadata for filtering) ───────────────────────────────────────
    {
        asset_id: String(data.asset_id ?? 'Pump-01')
    }
];

return msg;

const data = msg.payload;

if (!data) return null;

const lastSeverity = context.get('lastSeverity') || 'NORMAL';
const lastDiagnosis = context.get('lastDiagnosis') || 'none';

const currentSeverity = data.severity || 'NORMAL';
const currentDiagnosis = data.diagnosis?.most_likely || 'none';

// Recovery alert (anomaly -> NORMAL)
if (currentSeverity === 'NORMAL') {
    if (lastSeverity !== 'NORMAL') {
        context.set('lastSeverity', 'NORMAL');
        context.set('lastDiagnosis', 'none');

        const asset = data.asset_id || 'Pump-01';
        const timestamp = new Date().toLocaleString('en-GB', {
            timeZone: 'Africa/Casablanca'
        });

        msg.payload = {
            chatId: global.get('telegramChatId'),
            type: 'message',
            content: `✅ *NORMAL — ${asset}*\n\nMachine has returned to normal operation.\n_${timestamp}_`,
            parseMode: 'Markdown'
        };

        return msg;
    }

    return null;
}

// Only alert on WARNING or CRITICAL
if (!['WARNING', 'CRITICAL'].includes(currentSeverity)) {
    return null;
}

// Send alert if severity changed OR diagnosis changed
const shouldAlert =
    currentSeverity !== lastSeverity ||
    (currentDiagnosis !== lastDiagnosis && currentDiagnosis !== 'none');

if (!shouldAlert) return null;

context.set('lastSeverity', currentSeverity);
context.set('lastDiagnosis', currentDiagnosis);

const icon = currentSeverity === 'CRITICAL' ? '🔴' : '🟠';
const asset = data.asset_id || 'Pump-01';
const dominant = data.evidence?.dominant_feature || 'unknown';
const zScore = data.evidence?.z_score_deviation || 0;
const diagnosis = data.diagnosis?.most_likely || 'N/A';
const confidence = data.diagnosis?.confidence || 'N/A';
const recommendationMessage =
    data.recommendation?.message || 'No recommendation available.';
const action = data.recommendation?.action || 'N/A';
const priority = data.recommendation?.priority || 'N/A';

const timestamp = new Date().toLocaleString('en-GB', {
    timeZone: 'Africa/Casablanca'
});

const text =
`${icon} *${currentSeverity} ALERT — ${asset}*
━━━━━━━━━━━━━━━━━━━━━━
🕐 *Time:* ${timestamp}
📡 *Dominant Sensor:* ${dominant.toUpperCase()} (${zScore}σ)

🔬 *Fault Hypothesis:* ${diagnosis.replace(/_/g, ' ').toUpperCase()}
📊 *Confidence:* ${confidence}

📋 *Recommendation:*
${recommendationMessage}

⚡ *Action:* ${action.replace(/_/g, ' ')}
🎯 *Priority:* ${priority}
━━━━━━━━━━━━━━━━━━━━━━
_Pump-01 | Compressor Station A_`;

msg.payload = {
    chatId: global.get('telegramChatId'),
    type: 'message',
    content: text,
    parseMode: 'Markdown'
};

return msg;
